`validators.py`:

```
"""Validators V1..V6 over depot harness outputs.

Each validator subclasses ``Check`` (from ``checks_base``) and implements
``check(items) -> (passed, measured)``. Callers use ``VN().run(items)``.
"""
from __future__ import annotations

from checks_base import Check


def _is_int(value) -> bool:
    # bool is a subclass of int; a boolean is not a valid cents or unit count.
    return isinstance(value, int) and not isinstance(value, bool)


class V1(Check):
    """Every report row's value matches units x unit_cost."""

    name = "V1"
    FIELDS = ("sku", "wh", "units", "value_cents", "unit_cost")

    def check(self, items):
        mismatches = []
        for i, row in enumerate(items):
            if not isinstance(row, dict) or not all(k in row for k in self.FIELDS):
                mismatches.append((i, "missing field"))
                continue
            if not (
                isinstance(row["sku"], str)
                and isinstance(row["wh"], str)
                and _is_int(row["units"])
                and _is_int(row["value_cents"])
                and _is_int(row["unit_cost"])
            ):
                mismatches.append((i, "bad field type"))
                continue
            if row["value_cents"] != row["units"] * row["unit_cost"]:
                mismatches.append((i, "value_cents != units * unit_cost"))
        measured = {"rows": len(items), "mismatches": mismatches}
        return (not mismatches), measured


class V2(Check):
    """All notification types in the spec were seen across a set of runs.

    The required types are the notifications the spec says are emitted:
    OVERDRAWN (C20), EXPIRY (C13), AUDIT_MISMATCH (C22), REORDER (C14),
    SUPPLIER_SUSPENDED (C17).
    """

    name = "V2"
    REQUIRED_TYPES = (
        "OVERDRAWN",
        "EXPIRY",
        "AUDIT_MISMATCH",
        "REORDER",
        "SUPPLIER_SUSPENDED",
    )

    def check(self, items):
        seen = set()
        for run in items:
            for note in run:
                if isinstance(note, (tuple, list)) and len(note) > 0:
                    seen.add(note[0])
        missing = sorted(str(t) for t in self.REQUIRED_TYPES if t not in seen)
        measured = {
            "seen": sorted(str(s) for s in seen),
            "missing": missing,
        }
        return (not missing), measured


class V3(Check):
    """Two runs with the same seed are identical."""

    name = "V3"

    def check(self, items):
        differing = []
        for pair in items:
            if not (pair["a"] == pair["b"]):
                differing.append(pair["seed"])
        measured = {"pairs": len(items), "differing_seeds": differing}
        return (not differing), measured


class V4(Check):
    """Storage cost stayed within the budget on every day."""

    name = "V4"

    def check(self, items):
        over = []
        for entry in items:
            if entry["storage_cost_cents"] > entry["budget_cents"]:
                over.append(entry["day"])
        measured = {"days": len(items), "over_budget": over}
        return (not over), measured


class V5(Check):
    """Every clause has at least one (non-blank) test."""

    name = "V5"

    def check(self, items):
        untested = []
        for entry in items:
            tests = entry.get("tests") or []
            if not any(isinstance(t, str) and t.strip() for t in tests):
                untested.append(entry["clause_id"])
        measured = {"clauses": len(items), "untested": untested}
        return (not untested), measured


class V6(Check):
    """Results from two implementations agree on every compared pair."""

    name = "V6"

    def check(self, items):
        disagreements = []
        for pair in items:
            if not (pair["a"] == pair["b"]):
                disagreements.append(pair["key"])
        measured = {"pairs": len(items), "disagreements": disagreements}
        return (not disagreements), measured
```

`checks_base.py`:

```
"""The ``Check`` base class: a check never passes on nothing (brief 3, and E2's guard condition).

``Check.run(items)`` returns ``failed: empty input`` for empty or all-unmeasured input *before*
calling the subclass, and ``failed: nothing measured`` when the subclass measured nothing. The
harness's own checks (presence, reach, parity, mutation) subclass it, and so do the agent's
validators in E2's guard condition (the agent gets this file as ``checks_base.py``).

This file is standard-library only so it can be copied verbatim into the agent's repo.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class CheckResult:
    passed: bool
    measured: Any
    reason: str = ""

    def __iter__(self):  # allows ``passed, measured = check.run(x)``
        yield self.passed
        yield self.measured

    def __bool__(self) -> bool:
        return bool(self.passed)


def is_empty(value: Any) -> bool:
    """True for None, empty containers, and containers whose every leaf is None or empty."""
    if value is None:
        return True
    if isinstance(value, (str, bytes)):
        return len(value) == 0
    if isinstance(value, dict):
        return len(value) == 0 or all(is_empty(v) for v in value.values())
    if isinstance(value, (list, tuple, set, frozenset)):
        return len(value) == 0 or all(is_empty(v) for v in value)
    return False


class Check:
    """Subclasses implement ``check(items) -> (passed, measured)``; callers use ``run(items)``."""

    name = "check"

    def run(self, items: Any) -> CheckResult:
        if hasattr(items, "__next__"):  # a lazy source of runs: materialise before judging emptiness
            items = list(items)
        if is_empty(items):
            return CheckResult(False, None, "failed: empty input")
        try:
            passed, measured = self.check(items)
        except Exception as exc:  # a check that crashes has not passed
            return CheckResult(False, None, f"failed: {type(exc).__name__}: {exc}")
        if is_empty(measured):
            return CheckResult(False, measured, "failed: nothing measured")
        return CheckResult(bool(passed), measured, "" if passed else "failed")

    def check(self, items: Any) -> tuple[bool, Any]:  # pragma: no cover - abstract
        raise NotImplementedError
```
